def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    components = []

    # Find each separate 1-shaped object.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            todo = [(r, c)]
            seen.add((r, c))
            cells = []
            while todo:
                x, y = todo.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        todo.append((nx, ny))
            components.append(cells)

    # Color the one-cell rectangular halo around each object.
    for cells in components:
        r0 = max(0, min(r for r, c in cells) - 1)
        r1 = min(h - 1, max(r for r, c in cells) + 1)
        c0 = max(0, min(c for r, c in cells) - 1)
        c1 = min(w - 1, max(c for r, c in cells) + 1)
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if grid[r][c] == 0:
                    out[r][c] = 2

    # Color zero cells immediately inside the outlines.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if any(0 <= r + dr < h and 0 <= c + dc < w
                   and grid[r + dr][c + dc] == 1
                   for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                   if dr or dc):
                out[r][c] = 3
    return out
